// login.js
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Login() {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        setError("");  // Reset any previous errors

        try {
            const rawData = {
                userid: email,
                password: password,
            };

            const encodedData = encodeURIComponent(JSON.stringify(rawData));
            const apiURL = `https://novaoffice.novasoftwares.com/service.aspx?ApiVer=1&Devid=online&AppId=NV01&Lat=0&Lng=0&Control=auth&data=${encodedData}`;

            // Fetch API response
            const response = await fetch(apiURL);
            const data = await response.json();
            console.log("API Response:", data); // Add console log to see API response

            if (data?.Response?.Status === "1") {
                // Login successful, navigate to Dashboard with the data passed via state
                navigate("/dashboard", { state: { data } });
            } else {
                // Invalid credentials error message
                setError("Invalid credentials. Try again.");
            }
        } catch (err) {
            console.error("Login error:", err);
            setError("Something went wrong. Please try again.");
        }
    };

    return (
        <div className="container">
            <h1>Login</h1>
            <form onSubmit={handleLogin}>
                <div className="field">
                    <label>User ID</label>
                    <input
                        type="text"
                        name="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="Enter User ID"
                    />
                </div>
                <div className="field">
                    <label>Password</label>
                    <input
                        type="password"
                        name="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="Enter Password"
                    />
                </div>
                <button className="fluid ui button blue" type="submit">
                    Login
                </button>
                {error && <p style={{ color: "red", marginTop: "10px" }}>{error}</p>}
            </form>
            <div className="text" style={{ marginTop: "1rem", textAlign: "center" }}>
                Don't have an account? <Link to="/signup">Sign up</Link>
            </div>
        </div>
    );
}

export default Login;
